// ─────────────────────────────────────────────────────────────────────────────

type SectionName = "hero" | "about" | "education" | "skills" | "projects" | "achievements" | "contact";
type AchievementHighlight = "winner" | "topTen" | "topFive" | "none";

interface PortfolioImage {
  src: string;                 // Path relative to index.html, for example assets/img/photo.webp
  alt?: string;                // Optional. A sensible alt is generated when omitted.
}

interface LinkData {
  label: string;
  href: string;
  icon?: string;               // Bootstrap Icons class, for example bi-arrow-up-right
  overlayLabel?: string;       // Optional shorter label shown over a project image
}

interface SocialLink extends LinkData {
  icon: string;
}

interface Visibility {
  visible: boolean;            // false removes the section and its navigation link
  navigationLabel: string;
}

interface SectionBase extends Visibility {
  eyebrow: string;             // Small label above the large heading, without the 01 number
  title: string;
  titleAccent?: string;        // Text shown in the accent colour, usually "."
  description: string;
}

interface HeroSection extends Visibility {
  greeting: string;
  typedPrefix: string;
  typedPhrases: string[];
  intro: string;
  background: PortfolioImage;
  primaryAction: LinkData;
  secondaryAction: LinkData;
  scrollLabel: string;
  scrollAriaLabel: string;
  metaItems: string[];         // {year} is replaced automatically
}

interface FocusArea {
  name: string;
  icon: string;
}

interface Fact {
  label: string;
  value: string;               // {email}, {location}, and {name} are replaced automatically
  href?: string;
}

interface AboutSection extends SectionBase {
  photo: PortfolioImage;
  badge: { icon: string; title: string; subtitle: string };
  photoNote: string;
  overline: string;
  heading: string;
  paragraphs: string[];
  focusAreas: FocusArea[];
  facts: Fact[];
}

interface EducationItem {
  period: string;
  status?: string;
  title: string;
  subtitle?: string;
  institution: string;
}

interface EducationSection extends SectionBase {
  items: EducationItem[];
}

interface Skill {
  name: string;
  level: number;               // Whole number from 0 to 100
  icon: string;
}

interface ToolkitGroup {
  title: string;
  tools: string[];
}

interface SkillsSection extends SectionBase {
  items: Skill[];
  toolkitGroups: ToolkitGroup[];
}

interface Technology {
  name: string;
  icon: string;
}

interface ProjectStatus {
  text: string;
  icon: string;
}

interface Project {
  title: string;
  context: string;             // Small line above the project title
  category: string;            // Filters are generated automatically from these values
  categoryId?: string;         // Optional custom filter ID; otherwise derived from category
  description: string;
  image: PortfolioImage;
  technologies: Technology[];
  links: LinkData[];           // Use [] when there is no public link
  status?: ProjectStatus;      // Optional note shown when links is empty
  overlayLabel?: string;       // Optional image-overlay label when there is no public link
  featured?: boolean;          // true gives this project the wide editorial layout
}

interface ProjectsSection extends SectionBase {
  allFilterLabel: string;
  filterStatusTemplate: string; // Tokens: {count}, {label}, and {s} for pluralisation
  items: Project[];
}

interface Achievement {
  title: string;
  outcome: string;
  description: string;
  footnote: string;
  icon: string;
  highlight: AchievementHighlight;
}

interface AchievementsSection extends SectionBase {
  items: Achievement[];
}

interface ContactHeadingLine {
  text: string;
  accent?: string;             // Optional coloured text placed after text on the same line
}

interface ContactFormContent {
  nameLabel: string;
  namePlaceholder: string;
  emailLabel: string;
  emailPlaceholder: string;
  subjectLabel: string;
  subjectPlaceholder: string;
  messageLabel: string;
  messagePlaceholder: string;
  submitLabel: string;
  submitIcon: string;
  note: string;
  successMessage: string;      // {email} is replaced with personal.email
}

interface ContactSection extends Visibility {
  eyebrow: string;
  headingLines: ContactHeadingLine[];
  description: string;
  form: ContactFormContent;
}

interface FooterContent {
  copyright: string;           // The current year is inserted before this text
  backToTopLabel: string;
  wordmark: string;
}

interface PortfolioContent {
  personal: {
    fullName: string;
    shortName: string;
    initials: string;
    email: string;
    location: string;
    siteTitle: string;
    metaDescription: string;
  };
  ui: {
    skipToContent: string;
    homeAriaLabel: string;
    navigationAriaLabel: string;
    openNavigationLabel: string;
    closeNavigationLabel: string;
    socialLinksAriaLabel: string;
    focusAreasAriaLabel: string;
    projectFiltersAriaLabel: string;
    backToTopAriaLabel: string;
    imageFallbackText: string;
  };
  socialLinks: SocialLink[];
  sectionOrder: SectionName[]; // Controls both page order and navigation order
  hero: HeroSection;
  about: AboutSection;
  education: EducationSection;
  skills: SkillsSection;
  projects: ProjectsSection;
  achievements: AchievementsSection;
  contact: ContactSection;
  footer: FooterContent;
}

